// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BackgroundTaskRun) predicate.BackgroundTaskRun {
	return predicate.BackgroundTaskRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BackgroundTaskRun) predicate.BackgroundTaskRun {
	return predicate.BackgroundTaskRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BackgroundTaskRun) predicate.BackgroundTaskRun {
	return predicate.BackgroundTaskRun(sql.NotPredicates(p))
}
